mapper.select:
SELECT c.id AS chunk_id, c.document_id, d.title, d.source_name, d.source_url, d.file_name, d.pet_type, d.category, c.chunk_index, c.content, CAST(c.embedding_json AS CHAR) AS embedding_json, c.embedding_model, c.page_start, c.page_end FROM knowledge_chunk c INNER JOIN knowledge_document d ON d.id = c.document_id WHERE d.status = 'READY' AND d.review_status = 'APPROVED' AND d.consent_status != 'WITHDRAWN' AND (d.expires_at IS NULL OR d.expires_at > CURRENT_TIMESTAMP(6)) AND c.embedding_json IS NOT NULL
AND d.pet_type = #{petType}
AND d.category = #{category}
ORDER BY d.created_at DESC, c.chunk_index LIMIT #{limit}
